107	                    .frame(width: 12, height: 12)
108	                let name = GatewayChipState.shortName(origin)
109	                ZStack(alignment: .leading) {
110	                    Text(name).font(.system(size: 12, weight: .bold)).hidden()
111	                    Text(name).font(.system(size: 12, weight: inUse ? .bold : .regular))
112	                }
113	                .lineLimit(1)
114	                .truncationMode(.tail)
115	                .frame(maxWidth: 140, alignment: .leading)
116	                .fixedSize(horizontal: true, vertical: false)
117	            }
118	            .foregroundStyle(inUse ? Color.white : Color.primary)
119	            .padding(.horizontal, 8)
120	            .frame(height: 26)
121	            // Solid accent under white text: the one in use reads at a glance
122	            // over any page colour, light or dark. Every chip keeps an outline.
123	            .background {
124	                if inUse {
125	                    RoundedRectangle(cornerRadius: 6).fill(Color.accentColor)
126	                }
127	            }
