139	        // not be chosen at all; the dimmed look is the not-enabled trait.
140	        .disabled(!state.tappable)
141	        .opacity(!state.tappable && !inUse ? 0.6 : 1)
142	        .accessibilityLabel(GatewayChipState.shown(origin) + (inUse ? ", in use" : ""))
143	        .accessibilityValue(state.word)
144	        .accessibilityIdentifier("gateway-chip-\(GatewayChipState.shown(origin))")
145	    }
