147	    /// KiroCrew's `--ok`, `--warn`, `--danger` and `--muted`, as the system's
148	    /// own green, orange, red and grey, which adapt to light and dark.
149	    static func color(_ light: GatewayChipState.Light) -> Color {
150	        switch light {
